// Regression tests for every <meme-embed> used in the lecture notes and in
// embed_test.html (see fixtures/examples.json, generated by extract-examples.mjs).
//
// Each example is loaded on its own in harness.html, which reproduces the CSS of
// the lecture-notes site. The tests check
//   - the initial rendering of the canvas, against a reference image;
//   - that the expected tickboxes are present, labelled and set correctly;
//   - the rendering after toggling each tickbox (and that toggling back restores it);
//   - the rendering after dragging charges/currents, rigid dipoles and Gaussian surfaces;
//   - the time evolution of the dynamic (radiation) solver after a drag;
//   - behaviour at phone width and on window resize;
//   - that clicks, double clicks and touch drags behave as expected.

import {
    test, expect, examples, expectedCheckboxes, isDynamic, redrawDiffersFromFirstRender, hasGaussianSurface, dipolePairs,
    grabbableCharges, sampleCharges, dragTarget, gotoExample, waitForRender, embed, canvas,
    canvasPng, canvasPixels, countDifferentPixels, colourAt, classifyColour, toPage, mouseDrag,
    mouseDrawPath, loopAround, touchDrag, advance, checkbox, installPausedClock, DYNAMIC_RUNTIME_MS,
} from './helpers.js';

const PHONE_VIEWPORT = { width: 390, height: 700 };

/** Expected appearance of a charge at its own location, for the electrostatic solvers */
function expectedChargeColour(charge) {
    if (charge.isTestCharge) return 'other'; // light red / light blue
    return charge.charge > 0 ? 'red' : 'blue';
}

function isElectric(example) {
    return example.state.solver !== 'magnetostatic_direct';
}

for (const example of examples) {
    const charges = example.state.charges;
    const snap = name => [example.id, `${name}.png`];
    const frameMs = isDynamic(example) ? 16 : 0;

    test.describe(`${example.id} (${example.source})`, () => {

        test('initial render', async ({ page }) => {
            await gotoExample(page, example);

            // Canvas fills 90% of the embed width, with a 2:1 aspect ratio
            const box = await canvas(page).boundingBox();
            const embedBox = await embed(page).boundingBox();
            expect(box.width).toBeGreaterThan(0.85 * embedBox.width);
            expect(box.width).toBeLessThanOrEqual(embedBox.width);

            expect(await canvasPng(page)).toMatchSnapshot(snap('initial'));

            // Tickboxes: exactly the expected ones, with the right labels and states
            const expected = expectedCheckboxes(example);
            await expect(embed(page).locator('input[type=checkbox]')).toHaveCount(expected.length);
            for (const cb of expected) {
                const box = checkbox(page, cb.key);
                await expect(box).toBeVisible();
                await expect(embed(page).locator(`.${cb.key}-controls label`)).toHaveText(cb.label);
                if (cb.checked) await expect(box).toBeChecked();
                else await expect(box).not.toBeChecked();
                // the control must sit over the canvas, in its bottom-left corner
                const cbBox = await embed(page).locator(`.${cb.key}-controls`).boundingBox();
                expect(cbBox.x).toBeGreaterThanOrEqual(embedBox.x);
                expect(cbBox.y + cbBox.height).toBeLessThanOrEqual(embedBox.y + embedBox.height);
            }

            // Every visible charge is drawn at its location in the right colour
            if (isElectric(example)) {
                for (const i of grabbableCharges(example)) {
                    const c = charges[i];
                    expect(classifyColour(await colourAt(page, c)), `colour of charge ${i}`)
                        .toBe(expectedChargeColour(c));
                }
            }
        });

        for (const cb of expectedCheckboxes(example)) {
            test(`toggle "${cb.label}" tickbox`, async ({ page }) => {
                await gotoExample(page, example);
                const before = await canvasPixels(page);

                await checkbox(page, cb.key).click();
                await advance(page);
                if (cb.checked) await expect(checkbox(page, cb.key)).not.toBeChecked();
                else await expect(checkbox(page, cb.key)).toBeChecked();
                expect(await canvasPng(page)).toMatchSnapshot(snap(`toggle-${cb.key}`));
                if (!isDynamic(example))
                    expect(countDifferentPixels(before, await canvasPixels(page)),
                        'toggling should change the rendering').toBeGreaterThan(0);

                await checkbox(page, cb.key).click();
                await advance(page);
                if (cb.checked) await expect(checkbox(page, cb.key)).toBeChecked();
                else await expect(checkbox(page, cb.key)).not.toBeChecked();
                if (redrawDiffersFromFirstRender(example))
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`toggle-${cb.key}-back`));
                else if (!isDynamic(example))
                    expect(countDifferentPixels(before, await canvasPixels(page)),
                        'toggling twice should restore the original rendering').toBe(0);
            });
        }

        for (const i of sampleCharges(example)) {
            const from = charges[i];
            const to = dragTarget(from);

            test(`drag charge ${i}`, async ({ page }) => {
                await gotoExample(page, example);
                await mouseDrag(page, from, to, { frameMs });
                await advance(page);

                if (isDynamic(example)) {
                    // Radiation propagates outwards after the drag, then the animation stops
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`drag-${i}-t0`));
                    await advance(page, 500);
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`drag-${i}-t500ms`));
                    await advance(page, 1500);
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`drag-${i}-t2000ms`));
                    await advance(page, DYNAMIC_RUNTIME_MS);
                    const settled = await canvasPixels(page);
                    await advance(page, 1000);
                    expect(countDifferentPixels(settled, await canvasPixels(page)),
                        'animation should stop after the dynamic runtime').toBe(0);
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`drag-${i}-settled`));
                } else {
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`drag-${i}`));
                }

                const rigid = example.state.dipoleMode && from.dipoleWith !== undefined;
                if (isElectric(example) && !rigid && !from.isTestCharge) {
                    // The charge has moved to where it was dropped
                    expect(classifyColour(await colourAt(page, to)), 'charge at drop point')
                        .toBe(expectedChargeColour(from));
                    const stillThere = grabbableCharges(example).some(j => j !== i &&
                        Math.hypot(charges[j].x - from.x, charges[j].y - from.y) < 0.05);
                    const hiddenUnder = charges.some((c, j) => j !== i &&
                        Math.hypot(c.x - from.x, c.y - from.y) < 0.05);
                    if (!stillThere && !hiddenUnder)
                        expect(classifyColour(await colourAt(page, from)), 'original position vacated')
                            .not.toBe(expectedChargeColour(from));
                }
            });
        }

        if (!isDynamic(example)) {
            test('touch drag gives the same result as mouse drag', async ({ page, browser }) => {
                const i = grabbableCharges(example)[0];
                await gotoExample(page, example);
                await mouseDrag(page, charges[i], dragTarget(charges[i]));
                await advance(page);
                const viaMouse = await canvasPixels(page);

                const touchContext = await browser.newContext({
                    viewport: page.viewportSize(), deviceScaleFactor: 1, hasTouch: true,
                });
                const touchPage = await touchContext.newPage();
                await installPausedClock(touchPage);
                await gotoExample(touchPage, example);
                await touchDrag(touchPage, charges[i], dragTarget(charges[i]));
                await advance(touchPage);
                const viaTouch = await canvasPixels(touchPage);
                await touchContext.close();

                expect(countDifferentPixels(viaMouse, viaTouch)).toBe(0);
            });
        }

        test('clicking a charge, or clicking/double-clicking empty space, does not alter the embed', async ({ page }) => {
            // Embeds do not allow charges to be added, deleted or edited
            await gotoExample(page, example);
            const before = await canvasPixels(page);
            const onCharge = await toPage(page, charges[grabbableCharges(example)[0]]);
            const emptySpace = await toPage(page, { x: 0.03, y: 0.06 });

            await page.mouse.click(onCharge.x, onCharge.y);
            await advance(page);
            await page.mouse.click(emptySpace.x, emptySpace.y);
            await advance(page);
            await page.mouse.dblclick(emptySpace.x, emptySpace.y);
            await advance(page);

            await expect(page.locator('.charge-properties')).toHaveCount(0);
            if (!isDynamic(example) && !redrawDiffersFromFirstRender(example))
                expect(countDifferentPixels(before, await canvasPixels(page))).toBe(0);
        });

        if (!isDynamic(example)) {
            test('redrawing an unchanged state reproduces the first render', async ({ page }) => {
                const issue = redrawDiffersFromFirstRender(example);
                test.fail(!!issue, issue ?? '');
                await gotoExample(page, example);
                const before = await canvasPixels(page);
                // A click in empty space triggers a redraw without changing anything
                const p = await toPage(page, { x: 0.03, y: 0.06 });
                await page.mouse.click(p.x, p.y);
                await advance(page);
                expect(countDifferentPixels(before, await canvasPixels(page))).toBe(0);
            });
        }

        test('double-clicking a charge does not alter the embed', async ({ page }) => {
            await gotoExample(page, example);
            const before = await canvasPixels(page);
            const onCharge = await toPage(page, charges[grabbableCharges(example)[0]]);
            await page.mouse.dblclick(onCharge.x, onCharge.y);
            await advance(page);
            if (!isDynamic(example))
                expect(countDifferentPixels(before, await canvasPixels(page))).toBe(0);
        });

        for (const [i, j] of dipolePairs(example)) {
            const a = charges[i], b = charges[j];
            const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
            const isTest = !!a.isTestCharge;
            const name = `${isTest ? 'test ' : ''}dipole ${i}-${j}`;

            if (example.state.dipoleMode) {
                test(`rotate rigid ${name} by dragging one end`, async ({ page }) => {
                    await gotoExample(page, example);
                    // drag end `i` perpendicular to the dipole axis
                    const dx = b.x - a.x, dy = (b.y - a.y) / 2; // to CSS-pixel aspect
                    const len = Math.hypot(dx, dy);
                    const to = { x: a.x + (dy / len) * 0.1, y: a.y - (dx / len) * 0.2 };
                    await mouseDrag(page, a, to, { frameMs });
                    await advance(page);
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`rotate-${i}-${j}`));
                });

                test(`translate rigid ${name} by dragging its midpoint`, async ({ page }) => {
                    await gotoExample(page, example);
                    const to = dragTarget(mid);
                    await mouseDrag(page, mid, to, { frameMs });
                    await advance(page);
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`translate-${i}-${j}`));
                    // a rigid translation preserves the orientation; check an electric
                    // dipole has moved by looking for its charges at the new positions
                    if (isElectric(example) && !isTest) {
                        const shift = { x: to.x - mid.x, y: to.y - mid.y };
                        for (const c of [a, b])
                            expect(classifyColour(await colourAt(page, { x: c.x + shift.x, y: c.y + shift.y })))
                                .toBe(expectedChargeColour(c));
                    }
                });
            }

            if (expectedCheckboxes(example).some(cb => cb.key === 'dipole')) {
                test(`${name} ends move independently when not rigid`, async ({ page }) => {
                    await gotoExample(page, example);
                    const box = checkbox(page, 'dipole');
                    if (await box.isChecked()) await box.click();
                    await advance(page);
                    const to = dragTarget(a);
                    await mouseDrag(page, a, to, { frameMs });
                    await advance(page);
                    expect(await canvasPng(page)).toMatchSnapshot(snap(`nonrigid-drag-${i}`));

                    // Dragging the midpoint of a non-rigid dipole does nothing
                    const before = await canvasPixels(page);
                    const newMid = { x: (to.x + b.x) / 2, y: (to.y + b.y) / 2 };
                    await mouseDrag(page, newMid, dragTarget(newMid), { frameMs });
                    await advance(page);
                    if (!isDynamic(example))
                        expect(countDifferentPixels(before, await canvasPixels(page))).toBe(0);
                });
            }
        }

        if (hasGaussianSurface(example)) {
            test('draw Gaussian surface around one charge', async ({ page }) => {
                await gotoExample(page, example);
                await mouseDrawPath(page, loopAround(charges[0]));
                await advance(page);
                expect(await canvasPng(page)).toMatchSnapshot(snap('gaussian-one'));
            });

            test('draw Gaussian surface around all charges', async ({ page }) => {
                await gotoExample(page, example);
                const cx = charges.reduce((s, c) => s + c.x, 0) / charges.length;
                const cy = charges.reduce((s, c) => s + c.y, 0) / charges.length;
                const r = Math.max(...charges.map(c => Math.hypot(c.x - cx, (c.y - cy) / 2))) + 0.08;
                await mouseDrawPath(page, loopAround({ x: cx, y: cy }, r));
                await advance(page);
                expect(await canvasPng(page)).toMatchSnapshot(snap('gaussian-all'));
            });

            test('draw Gaussian surface enclosing no charge, then replace it', async ({ page }) => {
                await gotoExample(page, example);
                await mouseDrawPath(page, loopAround({ x: 0.5, y: 0.2 }, 0.06));
                await advance(page);
                expect(await canvasPng(page)).toMatchSnapshot(snap('gaussian-empty'));
                // Starting a new surface replaces the old one
                await mouseDrawPath(page, loopAround(charges[1]));
                await advance(page);
                expect(await canvasPng(page)).toMatchSnapshot(snap('gaussian-replaced'));
            });

            test('Gaussian surface persists while a charge is dragged through it', async ({ page }) => {
                await gotoExample(page, example);
                await mouseDrawPath(page, loopAround({ x: 0.5, y: 0.5 }, 0.08));
                await advance(page);
                await mouseDrag(page, charges[0], { x: 0.5, y: 0.5 });
                await advance(page);
                expect(await canvasPng(page)).toMatchSnapshot(snap('gaussian-drag-in'));
            });
        }

        test('renders at phone width', async ({ page }) => {
            await page.setViewportSize(PHONE_VIEWPORT);
            await gotoExample(page, example);
            const box = await canvas(page).boundingBox();
            expect(box.width).toBeLessThan(PHONE_VIEWPORT.width);
            expect(await canvasPng(page)).toMatchSnapshot(snap('phone'));
        });

        test('re-renders when the window is resized', async ({ page }) => {
            await gotoExample(page, example);
            const desktop = await canvas(page).boundingBox();
            await page.setViewportSize(PHONE_VIEWPORT);
            await waitForRender(page, 1);
            expect((await canvas(page).boundingBox()).width).toBeLessThan(PHONE_VIEWPORT.width);
            expect(await canvasPng(page)).toMatchSnapshot(snap('resized-to-phone'));

            await page.setViewportSize({ width: 900, height: 700 });
            await waitForRender(page, 1);
            // NB currently the canvas comes back 1px taller than it started, so this is
            // a separate snapshot rather than a comparison with the initial render
            const restored = await canvas(page).boundingBox();
            expect(Math.abs(restored.width - desktop.width)).toBeLessThanOrEqual(2);
            expect(Math.abs(restored.height - desktop.height)).toBeLessThanOrEqual(2);
            expect(await canvasPng(page)).toMatchSnapshot(snap('resized-back'));
        });
    });
}
